<?php require_once 'layout.php'; require_user(); $id=(int)($_GET['id']??0); $uid=current_user()['id']; $s=db()->prepare('SELECT * FROM orders WHERE id=? AND user_id=?'); $s->bind_param('ii',$id,$uid); $s->execute(); $o=$s->get_result()->fetch_assoc(); if(!$o) redirect('my_orders.php'); page_header('Order Confirmation'); ?><section class="success"><div class="check">✓</div><h1>Order Placed Successfully!</h1><p>Thank you! Your order has been placed.</p><div class="token"><span>Your Token Number</span><strong>#<?=$o['token_number']?></strong><p>Please collect your order at the counter.</p></div><div class="details"><p><b>Order ID</b> #<?=$o['token_number']?></p><p><b>Total Amount</b> ₹<?=number_format($o['total_amount'],0)?></p><p><b>Status</b> <?=$o['status']?></p><p><b>Orders Ahead</b> <?=orders_ahead($o)?></p><p><b>Estimated Waiting Time</b> <?=wait_minutes($o['status'])?> minutes</p></div><a class="button" href="my_orders.php">View My Orders</a></section><?php page_footer(); ?>
